"""Replay-only diagnostics for an action archive."""
import argparse,json
import numpy as np
import mw_tool


def diagnose(path):
    s=mw_tool.Session()
    a=np.load(path)['actions']
    ball_id=s.model.geom('objGeom').id
    basket_id=s.model.body('basket_goal').id
    ball_joint=s.model.body('bsktball').jntadr[0]
    adr=s.model.jnt_dofadr[ball_joint]
    basket_bodies={basket_id}
    for i in range(s.model.nbody):
        if s.model.body_parentid[i] in basket_bodies:basket_bodies.add(i)
    basket_geoms={i for i in range(s.model.ngeom) if s.model.geom_bodyid[i] in basket_bodies}
    def contacts():
        result=[]
        for c in s.data.contact:
            if c.dist<=.001 and ball_id in c.geom:
                other=next((int(g) for g in c.geom if g!=ball_id),ball_id)
                result.append({'geom':s.model.geom(other).name or str(other),'basket':other in basket_geoms,'dist':float(c.dist)})
        return result
    traces=[]
    for row in a:
        s.step(row)
        traces.append({'t':len(s.actions),'ball':s.obs[4:7].tolist(),'velocity':s.data.qvel[adr:adr+3].tolist(),'contacts':contacts(),'check':s.check()})
    final={'shape':list(a.shape),'check':s.check(),'sha':s.state_sha(),'ball':s.obs[4:7].tolist(),'velocity':s.data.qvel[adr:adr+3].tolist(),'opening':float(s.obs[3]),'contacts':contacts()}
    # This continuation is a diagnostic only; never saved as the submitted trajectory.
    continuation=[]
    for _ in range(35):
        s.step([0.,0.,0.,-1.])
        continuation.append({'t':len(s.actions),'ball':s.obs[4:7].tolist(),'velocity':s.data.qvel[adr:adr+3].tolist(),'contacts':contacts()})
    goal=s.target_pos[:2]
    crossing=[t for t in continuation if .20<t['ball'][2]<.25]
    final['crossings']=crossing
    final['rim_contacts_after_end']=[t for t in continuation if any(c['basket'] for c in t['contacts'])]
    return final,traces,continuation

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('path');p.add_argument('--json');args=p.parse_args()
    result,traces,continuation=diagnose(args.path)
    print(json.dumps(result,indent=2))
    if args.json:
        with open(args.json,'w') as f:json.dump({'result':result,'trajectory':traces,'continuation':continuation},f,indent=2)
