import numpy as np
import mw_tool

DEFAULT={'approach_n':34,'close_n':18,'rise_n':32,'carry_n':35,'settle_n':15,
         'gain':12.,'grasp_z':.016,'grasp_x':0.,'grasp_y':0.,'rise_z':.25,
         'approach_speed':.65,'rise_speed':.85,'carry_speed':.75,'lift_z':.34,
         'drop_z':.323,'offset_x':0.,'offset_y':-.003,'release_lift':0.,'settle_speed':.3}

def run(s,p,trace=False):
    s.reset();p={**DEFAULT,**p};states=[];stages={}
    ball=s.obs[4:7].copy();goal=s.target_pos.copy();goal[2]=.3
    grasp=ball.copy()+[p['grasp_x'],p['grasp_y'],0.];grasp[2]=p['grasp_z']
    def sample():
        if trace:states.append({'t':len(s.actions),'ball':s.obs[4:7].tolist(),'tcp':s.env.tcp_center.tolist(),'check':s.check()})
    def move(pos,grip,n,speed,name):
        for _ in range(int(n)):
            d=np.clip((pos-s.env.tcp_center)*p['gain'],-speed,speed)
            s.step([*d,grip]);sample()
        stages[name]={'t':len(s.actions),'ball':s.obs[4:7].tolist(),'tcp':s.env.tcp_center.tolist()}
    move(grasp,-1,p['approach_n'],p['approach_speed'],'approach')
    move(grasp,1,p['close_n'],.2,'close')
    move(np.array([*grasp[:2],p['rise_z']]),1,p['rise_n'],p['rise_speed'],'rise')
    offset=s.obs[4:7]-s.env.tcp_center
    carry=np.array([goal[0]+p['offset_x'],goal[1]+p['offset_y'],p['lift_z']])-offset
    move(carry,1,p['carry_n'],p['carry_speed'],'carry')
    offset=s.obs[4:7]-s.env.tcp_center
    drop=np.array([goal[0]+p['offset_x'],goal[1]+p['offset_y'],p['drop_z']])-offset
    move(drop,1,p['settle_n'],p['settle_speed'],'settle')
    release_t=len(s.actions);release_ball=s.obs[4:7].copy()
    release_grasp_distance=float(np.linalg.norm(s.obs[4:7]-s.env.tcp_center))
    hold=s.env.tcp_center.copy();hold[2]+=p['release_lift']
    best=(10.,0);best_actions=None;through=False;contacted=False;final=None
    ball_id=s.model.geom('objGeom').id
    basket_id=s.model.body('basket_goal').id
    basket_bodies={basket_id}
    for i in range(s.model.nbody):
        if s.model.body_parentid[i] in basket_bodies:basket_bodies.add(i)
    basket_geoms={i for i in range(s.model.ngeom) if s.model.geom_bodyid[i] in basket_bodies}
    for _ in range(40):
        d=np.clip((hold-s.env.tcp_center)*p['gain'],-.5,.5)
        s.step([*d,-1]);sample()
        for c in s.data.contact:
            if c.dist<=0 and ball_id in c.geom and any(g in basket_geoms for g in c.geom):contacted=True
        dist=float(s.info['obj_to_target'])
        if dist<best[0]:
            best=(dist,len(s.actions));best_actions=np.asarray(s.actions).copy()
            final=s.obs[4:7].copy()
        if .18<s.obs[6]<.23 and np.linalg.norm(s.obs[4:6]-goal[:2])<.006:through=True
    r={'best_dist':best[0],'terminal_t':best[1],'through':through,'rim_contact':contacted,'terminal_ball':final.tolist(),'release_t':release_t,'release_ball':release_ball.tolist(),'release_grasp_distance':release_grasp_distance,'stages':stages}
    return r,best_actions,states

if __name__=='__main__':
    import json
    s=mw_tool.Session()
    for n in [24,28,32,36]:
        r,a,states=run(s,{'approach_n':n},True)
        print(n,json.dumps(r),flush=True)
        if r['best_dist']<.02:
            s.save_trajectory(a,path=f'/app/output/experiments/compact_{n}.npz',meta=r)
